/* Cinematic navigation uses layered perspective, not a volumetric environment. */
(()=>{const reduced=matchMedia('(prefers-reduced-motion:reduce)').matches,rooms=[['genesis','The origin','01','The moment before the touch'],['explorer','The living atlas','02','Follow the illuminated lines'],['scanner','The palm studio','03','Capture your own perspective'],['laboratory','The image laboratory','04','Look beneath the surface'],['reading','Your field notes','05','Two palms, one exploration'],['oracle','The oracle room','06','A conversation with curiosity'],['heritage','The heritage room','07','A gallery of painted symbols'],['process','Behind the wonder','08','The methods behind the magic']];const flight=document.querySelector('#camera-flight'),menu=document.querySelector('#room-menu'),canvas=document.querySelector('#gold-rain'),ctx=canvas.getContext('2d');let width=0,height=0,dpr=1,particles=[],dustFrame=0,lastDust=0,activeRoom=0,busy=false,tour=false,tourTimer=0,flightTimers=[],observer=null,visible=true;
const rand=(a,b)=>a+Math.random()*(b-a);function newParticle(burst=false){return{x:rand(0,width),y:burst?rand(-height*.35,15):rand(-height,height),vx:rand(-.28,.38),vy:burst?rand(1.7,4.4):rand(.32,.95),r:burst?rand(.8,2.6):rand(.45,1.6),phase:rand(0,6.3),life:burst?rand(140,250):Infinity,burst,spin:rand(0,6.3)}}function resize(){width=innerWidth;height=innerHeight;dpr=Math.min(devicePixelRatio||1,1.4);canvas.width=width*dpr;canvas.height=height*dpr;ctx.setTransform(dpr,0,0,dpr,0,0);particles=Array.from({length:width<800?48:95},()=>newParticle())}function shower(){if(reduced||document.body.classList.contains('paused'))return;particles.push(...Array.from({length:width<800?70:140},()=>newParticle(true)));if(particles.length>380)particles=particles.slice(-380)}function dust(t){if(!visible)return;dustFrame=requestAnimationFrame(dust);if(t-lastDust<32)return;const dt=Math.min((t-lastDust)/33.3,2);lastDust=t;ctx.clearRect(0,0,width,height);if(reduced)return;const paused=document.body.classList.contains('paused');for(let i=particles.length-1;i>=0;i--){const p=particles[i];if(!paused){p.x+=(p.vx+Math.sin(t*.0004+p.phase)*.22)*dt;p.y+=p.vy*dt;p.life-=dt}if(p.y>height+10||p.life<0){if(p.burst){particles.splice(i,1);continue}p.y=-10;p.x=rand(0,width)}const twinkle=.32+.5*(.5+.5*Math.sin((paused?0:t*.002)+p.phase));ctx.fillStyle=`rgba(255,${Math.round(187+p.r*18)},115,${twinkle})`;ctx.shadowBlur=p.r>1.4?7:0;ctx.shadowColor='#e9bb64';ctx.beginPath();ctx.arc(p.x,p.y,p.r,0,Math.PI*2);ctx.fill();if(p.r>1.5){ctx.shadowBlur=0;ctx.strokeStyle=`rgba(255,228,163,${twinkle*.7})`;ctx.lineWidth=.6;ctx.beginPath();ctx.moveTo(p.x-p.r*2.2,p.y);ctx.lineTo(p.x+p.r*2.2,p.y);ctx.moveTo(p.x,p.y-p.r*2.2);ctx.lineTo(p.x,p.y+p.r*2.2);ctx.stroke()}}ctx.shadowBlur=0}resize();addEventListener('resize',resize,{passive:true});if(!reduced){dustFrame=requestAnimationFrame(dust);shower()}document.querySelector('#dust-shower').onclick=shower;document.addEventListener('visibilitychange',()=>{visible=!document.hidden;if(!visible)cancelAnimationFrame(dustFrame);else if(!reduced){lastDust=0;dustFrame=requestAnimationFrame(dust)}});
menu.innerHTML=rooms.map(([id,label,note,copy])=>`<button data-room="${id}"><span>${note}</span><div><strong>${label}</strong><small>${copy}</small></div><b>↗</b></button>`).join('');function closeMenu(){menu.hidden=true;document.querySelector('#room-menu-toggle').setAttribute('aria-expanded','false')}document.querySelector('#room-menu-toggle').onclick=()=>{const open=menu.hidden;menu.hidden=!open;document.querySelector('#room-menu-toggle').setAttribute('aria-expanded',String(open))};document.addEventListener('keydown',e=>{if(e.key==='Escape')closeMenu()});document.addEventListener('click',e=>{if(!e.target.closest('.journey-dock'))closeMenu()});function markRoom(i){activeRoom=i;document.querySelector('#current-room-label').textContent=rooms[i][1];menu.querySelectorAll('[data-room]').forEach(b=>{const a=b.dataset.room===rooms[i][0];b.classList.toggle('room-current',a);if(a)b.setAttribute('aria-current','location');else b.removeAttribute('aria-current')});document.querySelector('#journey-next').setAttribute('aria-label',`Travel to ${rooms[(i+1)%rooms.length][1]}`)}function currentVisible(){let best=0,index=activeRoom;rooms.forEach(([id],i)=>{const r=document.getElementById(id).getBoundingClientRect(),amount=Math.max(0,Math.min(r.bottom,innerHeight)-Math.max(r.top,0));if(amount>best){best=amount;index=i}});return index}let scrollQueued=false;addEventListener('scroll',()=>{if(busy||scrollQueued)return;scrollQueued=true;requestAnimationFrame(()=>{markRoom(currentVisible());scrollQueued=false})},{passive:true});markRoom(currentVisible());
function stopTour(){tour=false;clearTimeout(tourTimer);document.querySelector('#tour-control').textContent='▷';document.querySelector('#tour-control').setAttribute('aria-label','Start cinematic tour');document.querySelector('#tour-control').title='Start cinematic tour';document.body.classList.remove('tour-running')}function finishFlight(target,entering){flightTimers.forEach(clearTimeout);flightTimers=[];document.body.classList.remove('camera-in-flight');flight.classList.remove('flight-active');flight.setAttribute('aria-hidden','true');if(entering)entering.classList.remove('room-arrival');document.querySelectorAll('.room-departure').forEach(s=>s.classList.remove('room-departure'));busy=false;const i=rooms.findIndex(r=>r[0]===target.id);if(i>=0)markRoom(i);if(tour)scheduleTour()}
function travel(id,options={}){const target=document.getElementById(id);if(!target||busy)return;closeMenu();if(!options.touring)stopTour();const destination=rooms.find(r=>r[0]===id),r=target.getBoundingClientRect();if(Math.abs(r.top)<65&&!options.force){if(tour)scheduleTour();return}if(reduced||document.body.classList.contains('paused')){target.scrollIntoView({behavior:'instant',block:'start'});history.pushState(null,'','#'+id);if(destination)markRoom(rooms.indexOf(destination));document.querySelector('#travel-announcement').textContent='Entered '+(destination?.[1]||id);if(tour)scheduleTour();return}busy=true;const leaving=document.getElementById(rooms[currentVisible()][0]);const index=destination?rooms.indexOf(destination):activeRoom;const angle=index%2?24:-24;document.documentElement.style.setProperty('--flight-angle',angle+'deg');document.documentElement.style.setProperty('--arrival-angle',(-angle*.7)+'deg');document.querySelector('#flight-room-title').textContent=destination?.[1]||'The sanctuary';document.querySelector('#flight-room-number').textContent=destination?destination[2]+' / 08':'THE PALM ATELIER';document.querySelector('#travel-announcement').textContent='Travelling to '+(destination?.[1]||'the sanctuary');document.body.classList.add('camera-in-flight');flight.setAttribute('aria-hidden','false');flight.classList.add('flight-active');leaving.classList.add('room-departure');shower();flightTimers.push(setTimeout(()=>{leaving.classList.remove('room-departure');target.scrollIntoView({behavior:'instant',block:'start'});history.pushState(null,'','#'+id);target.classList.add('room-arrival');},700));flightTimers.push(setTimeout(()=>finishFlight(target,target),1900))}window.palmaTravel=travel;menu.querySelectorAll('[data-room]').forEach(b=>b.onclick=()=>travel(b.dataset.room));document.querySelector('#journey-next').onclick=()=>travel(rooms[(activeRoom+1)%rooms.length][0]);document.addEventListener('click',e=>{const a=e.target.closest('a[href^="#"]');if(!a||a.hasAttribute('download'))return;const id=a.getAttribute('href').slice(1)||'genesis';if(!document.getElementById(id))return;e.preventDefault();travel(id)});function scheduleTour(){clearTimeout(tourTimer);tourTimer=setTimeout(()=>{if(!tour)return;travel(rooms[(activeRoom+1)%rooms.length][0],{touring:true,force:true})},6000)}function startTour(){if(tour){stopTour();return}if(reduced){document.querySelector('#travel-announcement').textContent='Reduced motion is enabled. Choose a room from the navigation wheel to explore without camera animation.';closeMenu();menu.hidden=false;document.querySelector('#room-menu-toggle').setAttribute('aria-expanded','true');return}tour=true;document.body.classList.add('tour-running');document.querySelector('#tour-control').textContent='Ⅱ';document.querySelector('#tour-control').setAttribute('aria-label','Stop cinematic tour');document.querySelector('#tour-control').title='Stop cinematic tour';travel(rooms[(activeRoom+1)%rooms.length][0],{touring:true,force:true})}document.querySelector('#tour-control').onclick=startTour;document.querySelectorAll('[data-tour]').forEach(b=>b.onclick=startTour);addEventListener('wheel',()=>{if(tour&&!busy)stopTour()},{passive:true});addEventListener('touchstart',e=>{if(tour&&!busy&&!e.target.closest('.journey-dock'))stopTour()},{passive:true});addEventListener('popstate',()=>{if(!busy){const target=document.getElementById(location.hash.slice(1));if(target)target.scrollIntoView({behavior:'instant',block:'start'});markRoom(currentVisible())}});new MutationObserver(()=>{if(tour&&document.body.classList.contains('paused'))stopTour()}).observe(document.body,{attributes:true,attributeFilter:['class']});document.addEventListener('visibilitychange',()=>{if(document.hidden)stopTour()});
})();
